mapper.insert:
INSERT INTO phone_active_info (
    sn, phone_type, imei1, imei2, model, info_id, store_id,
    skip_api_call, old_phone_status, old_phone_usage_months,
    create_time, create_by, nick_name, update_time, update_by
) VALUES (
    #{sn}, #{phoneType}, #{imei1}, #{imei2}, #{model}, #{infoId}, #{storeId},
    #{skipApiCall}, #{oldPhoneStatus}, #{oldPhoneUsageMonths},
    #{createTime}, #{createBy}, #{nickName}, #{updateTime}, #{updateBy}
)

mapper.update:
UPDATE phone_active_info
phone_type = #{phoneType}, imei1 = #{imei1}, imei2 = #{imei2}, model = #{model}, info_id = #{infoId}, store_id = #{storeId}, skip_api_call = #{skipApiCall}, old_phone_status = #{oldPhoneStatus}, old_phone_usage_months = #{oldPhoneUsageMonths}, update_time = now() , update_by = #{updateBy}
WHERE id = #{id}

mapper.select:
SELECT
    ,
    li.name, li.phone_num, sd.dept_name AS store_name
FROM phone_active_info pai
LEFT JOIN leave_information li ON pai.info_id = li.id
LEFT JOIN sys_dept sd ON pai.store_id = sd.dept_id

     AND pai.id = #{id}
     AND pai.sn = #{sn}
     AND pai.phone_type = #{phoneType}
     AND pai.imei1 = #{imei1}
     AND pai.imei2 = #{imei2}
     AND pai.model = #{model}
     AND pai.create_by = #{createBy}
     AND pai.nick_name like CONCAT('%', #{nickName}, '%')
     AND pai.store_id = #{storeId}
     AND pai.skip_api_call = #{skipApiCall}
     AND pai.old_phone_status = #{oldPhoneStatus}
     AND li.name LIKE CONCAT('%', #{name}, '%')
     AND li.phone_num LIKE CONCAT('%', #{phoneNum}, '%')

ORDER BY pai.create_time DESC

SELECT
    ,
    ,
    ,
    li.name, li.phone_num, sd.dept_name AS store_name
FROM phone_active_info pai
LEFT JOIN phone_active_detail pad ON pai.id = pad.order_id
LEFT JOIN phone_order_contract poc ON pai.id = poc.order_id
LEFT JOIN leave_information li ON pai.info_id = li.id
LEFT JOIN sys_dept sd ON pai.store_id = sd.dept_id

     AND pai.id = #{id}
     AND pai.sn = #{sn}
     AND pai.phone_type = #{phoneType}
     AND pai.imei1 = #{imei1}
     AND pai.imei2 = #{imei2}
     AND pai.model = #{model}
     AND pad.activated = #{activated}
     AND pad.sys_time = #{sysTime}
     AND poc.contract_id = #{contractId}
     AND pai.create_by = #{createBy}
     AND pai.nick_name like CONCAT('%', #{nickName}, '%')
     AND pai.store_id = #{storeId}
     AND pai.skip_api_call = #{skipApiCall}
     AND pai.old_phone_status = #{oldPhoneStatus}
     AND poc.signature_model like CONCAT('%', #{signatureModel}, '%')
     AND poc.signature_imei like CONCAT('%', #{signatureImei}, '%')
     AND poc.signature_date = #{signatureDate}
     AND li.name LIKE CONCAT('%', #{name}, '%')
     AND li.phone_num LIKE CONCAT('%', #{phoneNum}, '%')
     AND poc.signature_imei is not null

ORDER BY pai.create_time DESC

SELECT DATE_FORMAT(pai.create_time, '%Y-%m-%d') AS day, COUNT(*) AS orderCount, SUM(CASE WHEN pad.activated = 1 THEN 1 ELSE 0 END) AS activatedCount, SUM(CASE WHEN poc.signature_date IS NOT NULL AND poc.signature_date != '' THEN 1 ELSE 0 END) AS signedCount FROM phone_active_info pai LEFT JOIN phone_active_detail pad ON pai.id = pad.order_id LEFT JOIN phone_order_contract poc ON pai.id = poc.order_id WHERE DATE(pai.create_time) >= STR_TO_DATE(#{startDate}, '%Y-%m-%d') AND DATE(pai.create_time) <= STR_TO_DATE(#{endDate}, '%Y-%m-%d')
AND pai.create_by = #{createBy}
GROUP BY DATE_FORMAT(pai.create_time, '%Y-%m-%d') ORDER BY day ASC

SELECT , ,
FROM phone_active_info pai LEFT JOIN phone_active_detail pad ON pai.id = pad.order_id LEFT JOIN phone_order_contract poc ON pai.id = poc.order_id
AND pai.create_by = #{createBy}
ORDER BY pai.create_time DESC LIMIT #{limit}
